```python
class Vehicle:
    def __init__(self):
        self.type = "Generic Vehicle"

    def info(self):
        return self.type

class Car(Vehicle):
    def __init__(self):
        super().__init__()
        self.type = "Car"

    def info(self):
        return "This is a " + self.type

class ElectricCar(Car):
    def __init__(self):
        super().__init__()
        self.battery = "Lithium"

def main():
    e = ElectricCar()
    print(e.info())
    print(e.battery)

main()
